<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><div><h2><?= esc($plan->title) ?></h2><span class="badge bg-primary"><?= $plan->is_locked?'Locked':'Generated' ?></span></div><div><a class="btn btn-outline-secondary" href="<?= base_url('school/admission/seat-plans/'.$plan->token.'/pdf') ?>">Download PDF</a><?php if(!$plan->is_locked): ?> <?= form_open('school/admission/seat-plans/'.$plan->token.'/lock',['class'=>'d-inline']) ?><button class="btn btn-warning" onclick="return confirm('Lock this plan?')">Lock plan</button><?= form_close() ?><?php endif ?></div></div><div class="alert alert-light"><strong>Test:</strong> <?= esc($test->title) ?> · <strong>Date:</strong> <?= esc($test->test_date) ?> · <strong>Candidates:</strong> <?= count($allocations) ?></div><?php foreach($rooms as $room): ?><div class="card shadow-sm mb-3"><div class="card-header"><strong><?= esc($room->room_name_snapshot) ?> (<?= esc($room->room_no_snapshot) ?>)</strong> · <?= count($byRoom[$room->room_id]??[]) ?>/<?= $room->capacity ?></div><div class="card-body table-responsive"><table class="table table-sm"><thead><tr><th>Seat</th><th>Application</th><th>Candidate</th><th>Date of birth</th></tr></thead><tbody><?php foreach($byRoom[$room->room_id]??[] as $a): ?><tr><td><?= esc($a->seat_no) ?></td><td><?= esc($a->application_no_snapshot) ?></td><td><?= esc($a->student_name) ?></td><td><?= esc($a->dob) ?></td></tr><?php endforeach ?></tbody></table></div></div><?php endforeach ?></div>
